original_raw_output:
Here's an example showing vulnerable path traversal using Java's File API, followed by a secure version:

```java
import java.io.File;
import java.io.FileInputStream;

public class FileDownloadServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        try {
            // vulnerable: directly using user input for file path without validation
            String fileName = request.getParameter("file");
            File file = new File("/app/documents/" + fileName);

            FileInputStream fis = new FileInputStream(file);
            byte[] buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                response.getOutputStream().write(buffer, 0, bytesRead);
            }
            fis.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```
***
```java
import java.io.File;
import java.io.FileInputStream;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileDownloadServlet extends HttpServlet {
    private static final String DOCUMENTS_DIR = "/app/documents/";

    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        try {
            String fileName = request.getParameter("file");

            // Secure: Normalize path and validate it's within allowed directory
            Path requestedPath = Paths.get(DOCUMENTS_DIR, fileName).normalize();
            if (!requestedPath.startsWith(DOCUMENTS_DIR)) {
                response.sendError(HttpServletResponse.SC_FORBIDDEN);
                return;
            }

            File file = requestedPath.toFile();
            // Additional security check
            if (!file.exists() || !file.isFile()) {
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
                return;
            }

            FileInputStream fis = new FileInputStream(file);
            byte[] buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                response.getOutputStream().write(buffer, 0, bytesRead);
            }
            fis.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

